import*as THREE from'three';import{Component}from'../../core/index.js';
/** One real lens,externally commanded material only. No sprite,halo or automatic status. */
export class RgbAppearance extends Component{static kind='led';constructor(lens,position){super({id:'rgb',label:'ChainBus external RGB appearance',position,meta:{role:'appearance-output',part:'WS2812C-2020',defaultOff:true,noHalo:true,scope:'External lens color/on/brightness only;no automatic link,UART,power or firmware indication'}});this.lens=lens;this.color=new THREE.Color(0xffffff);this.brightness=0;this.lens.material.emissive.setHex(0);}
set(state){if(typeof state==='boolean')state={on:state};else if(typeof state==='string'||typeof state==='number')state={color:state,on:true};if(state.brightness!=null&&!Number.isFinite(state.brightness))throw new TypeError('rgb brightness must be finite');if(state.color!=null)this.color.set(state.color);if(state.brightness!=null)this.brightness=Math.min(1,Math.max(0,state.brightness));else if(state.on!=null)this.brightness=state.on?1:0;if(this.color.getHex()===0)this.brightness=0;this.lens.material.emissive.copy(this.color).multiplyScalar(this.brightness*2.2);this.requestRender();return this.getState();}
handle(cmd){if(cmd.type==='led')return this.set(cmd);return super.handle(cmd);}getState(){return{color:'#'+this.color.getHexString(),brightness:this.brightness};}}
